s = rep(s, "*v9.1 note (2026-10-11) — VERSION NOTE", NOTE + "\n\n*v9.1 note (2026-10-11) — VERSION NOTE", 1)
s = s.rstrip("\n") + DIGEST + "\n"
io.open(DST, "w", encoding="utf-8").write(s)

a = io.open(SRC, encoding="utf-8").read()
m1 = a.split("# PART I — THE STRICT FORMALISM", 1)[1]
m2 = s.split("# PART I — THE STRICT FORMALISM", 1)[1].split("# LINEAGE APPENDIX", 1)[0]
print("v9.1 body (post-Part-I-marker) preserved prefix:", m2.startswith(m1[:4000]))
p1 = a.split("# PART I — THE STRICT FORMALISM", 1)[1].split("# PART II", 1)[0]
p2 = s.split("# PART I — THE STRICT FORMALISM", 1)[1].split("# PART II", 1)[0]
print("Part I byte-identical v9.1 == v9.2:", p1 == p2)
print("DESCRIPTIVE label:", s.count("DESCRIPTIVE LINEAGE"), "| digest rows:", s.count("(v10.9)") + s.count("(v10.5)"))
print("bytes:", len(s.encode("utf-8")), "lines:", s.count("\n") + 1)
